-- Timetable re-test 63 (T164, T166a; docs/plans/timetable-plan.md). The daily cleanup now deletes events 90 days after they end, which takes their topics and the people's Save and I'm going rows with them (personal data); events_ends lets it find them without reading the whole table. events_place makes the table refuse an in-person event with no city (an online event has none; events_online_no_city already refuses an online one with a city). The table is empty in every environment until the feed job (Timetable PR 4), so the check validates at once. Expand only: one index and one check.
ALTER TABLE "events" ADD CONSTRAINT "events_place" CHECK ("events"."online" or "events"."city" is not null);--> statement-breakpoint
CREATE INDEX "events_ends" ON "events" USING btree ("ends_at");
